  "왜": "내놓는 힘이 드러나 있지만 뿌리가 없어요. 돈이 첫째라 돈 얘기를 자주 하는데 실행은 늦는 사람이에요. 이달 운에 돈 기운이 와서 「이번엔 진짜」가 나올 수 있어요. 이달 한 약속 하나만 골라 다음 달에 지켜지는지 보세요."
